/* Nova Bastion 3D service worker.
 *
 * Offline-first PWA shell. Generated by scripts/build-sw.js; do not edit the
 * PRECACHE list by hand, regenerate it. Version: novabastion-3d-beta1
 *
 * Notes:
 * - cache-first for all same-origin game assets.
 * - navigation requests fall back to the cached index.html when offline.
 * - cross-origin requests are left alone (the game has no runtime CDN deps).
 * - PeerJS cloud signaling is a websocket, not fetch, so nothing to cache.
 */
'use strict';

const CACHE_NAME = "novabastion-3d-beta1";
const INDEX_URL = 'index.html';
const PRECACHE = [
  "css/refinement.css",
  "css/style.css",
  "icons/icon-128.png",
  "icons/icon-144.png",
  "icons/icon-152.png",
  "icons/icon-192.png",
  "icons/icon-384.png",
  "icons/icon-512.png",
  "icons/icon-72.png",
  "icons/icon-96.png",
  "icons/icon-maskable-512.png",
  "index.html",
  "js/ai.js",
  "js/audio.js",
  "js/config.js",
  "js/demo3d.js",
  "js/enemies.js",
  "js/events.js",
  "js/game.js",
  "js/gamepad.js",
  "js/ira.js",
  "js/main.js",
  "js/net.js",
  "js/render3d.js",
  "js/sectors.js",
  "js/sim.js",
  "js/story.js",
  "js/towers.js",
  "js/ui.js",
  "js/vendor/fonts/orbitron-var.woff2",
  "js/vendor/fonts/rajdhani-500.woff2",
  "js/vendor/fonts/rajdhani-600.woff2",
  "js/vendor/fonts/rajdhani-700.woff2",
  "js/vendor/peerjs.min.js",
  "js/vendor/three.min.js",
  "manifest.json"
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
      .catch((err) => {
        // A single failed asset must not brick the game page.
        console.error('[NB3D sw] precache failed:', err);
        return self.skipWaiting();
      })
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) =>
        Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)))
      )
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return; // not ours, ignore

  if (req.mode === 'navigate') {
    // Offline story: the SPA always lands back on the cached title screen.
    event.respondWith(
      fetch(req)
        .then((res) => {
          if (res && res.ok) {
            const copy = res.clone();
            caches.open(CACHE_NAME).then((c) => c.put(INDEX_URL, copy)).catch(() => {});
          }
          return res;
        })
        .catch(() => caches.match(INDEX_URL))
    );
    return;
  }

  event.respondWith(
    caches.match(req).then((cached) => {
      if (cached) return cached;
      return fetch(req).then((res) => {
        if (res && res.ok) {
          const copy = res.clone();
          caches.open(CACHE_NAME).then((c) => c.put(req, copy)).catch(() => {});
        }
        return res;
      });
    })
  );
});
